+document.addEventListener('DOMContentLoaded', () => {
+    const disclosureButtons = document.querySelectorAll('button[aria-expanded]');
+
+    disclosureButtons.forEach(button => {
+        // Get the controlled element ID from aria-controls
+        const controlsId = button.getAttribute('aria-controls');
+        const panel = document.getElementById(controlsId);
+
+        if (!panel) return;
+
+        // Ensure the initial state is collapsed
+        // Following recommendation: add 'hidden' via JS at init
+        button.setAttribute('aria-expanded', 'false');
+        panel.hidden = true;
