+}
+
+.container {
+    max-width: 800px;
+    margin: 0 auto;
+    padding: 0 1.5rem;
+}
+
+/* Skip Link */
+.skip-link {
+    position: absolute;
+    top: -40px;
+    left: 0;
+    background: var(--primary-color);
+    color: white;
+    padding: 8px;
+    z-index: 100;
+    transition: top 0.2s;
+}
+
+.skip-link:focus {
+    top: 0;
+}
+
+/* Header */
+header {
+    padding: 4rem 0 2rem;
+    text-align: center;
+}
+
+h1 {
+    font-size: 2.5rem;
+    font-weight: 800;
+    letter-spacing: -0.025em;
+    margin-bottom: 0.5rem;
+}
+
+.subtitle {
+    font-size: 1.125rem;
+    color: var(--text-muted);
+}
+
+/* Main content */
+main {
+    padding-bottom: 4rem;
+    outline: none; /* Focus handled by tabindex */
+}
+
+.faq-list {
+    display: flex;
+    flex-direction: column;
+    gap: 1rem;
+}
+
+.example {
+    background-color: var(--card-bg);
+    border: 1px solid var(--border-color);
+    border-radius: 0.75rem;
+    box-shadow: var(--shadow);
+    overflow: hidden;
+    transition: box-shadow 0.2s ease;
+}
+
+.example:hover {
+    box-shadow: var(--shadow-md);
+}
+
+h2 {
+    font-size: 1rem;
+    margin: 0;
+}
+
+button[aria-expanded] {
+    width: 100%;
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 1.25rem 1.5rem;
+    background: none;
+    border: none;
+    font-family: inherit;
+    font-size: 1.125rem;
+    font-weight: 600;
+    color: var(--text-main);
+    text-align: left;
+    cursor: pointer;
+    transition: color 0.2s;
+}
+
+button[aria-expanded]:hover,
+button[aria-expanded]:focus {
+    color: var(--primary-color);
+}
+
+button[aria-expanded]:focus {
+    outline: 2px solid var(--primary-color);
+    outline-offset: -2px;
+}
+
+/* Icon for the button */
+button[aria-expanded]::after {
+    content: '';
+    display: inline-block;
+    width: 12px;
+    height: 12px;
+    border-right: 2px solid currentColor;
+    border-bottom: 2px solid currentColor;
+    transform: rotate(45deg);
+    margin-left: 1rem;
+    transition: transform 0.2s ease;
+    flex-shrink: 0;
+}
+
+button[aria-expanded="true"]::after {
+    transform: rotate(-135deg);
+}
+
+.details {
+    padding: 0 1.5rem 1.5rem;
+    color: var(--text-muted);
+    font-size: 1rem;
+}
+
+/* Hidden by default, JS will manage this but we provide CSS fallback */
+.details[hidden] {
+    display: none;
+}
+
+/* Footer */
+footer {
+    padding: 2rem 0;
+    border-top: 1px solid var(--border-color);
+    text-align: center;
+    color: var(--text-muted);
+    font-size: 0.875rem;
+}
+
+@media (max-width: 640px) {
+    header {
+        padding: 3rem 0 1.5rem;
+    }
+    h1 {
+        font-size: 2rem;
+    }
+    button[aria-expanded] {
+        padding: 1rem 1.25rem;
+        font-size: 1rem;
+    }
+    .details {
+        padding: 0 1.25rem 1.25rem;
+    }
+}
+
